/**
 * "At a glance" — a short plain-English summary written FROM the profile's own data (2026-11-18).
 *
 * Why: contractor pages were 46–69% shared template, leaving ~100–250 words about the company,
 * and Google parked 20K+ of them as "Crawled — currently not indexed". These sentences are
 * unique per company because every clause is computed from that company's figures.
 *
 * Rules (a number is a claim — CLAUDE.md):
 *  - every figure comes from an argument; nothing is estimated or generated by a model;
 *  - a sentence whose inputs are missing is omitted, never written with a 0 or a guess;
 *  - year-over-year compares the two most recent COMPLETE fiscal years (the current FY is partial);
 *  - net obligations can be negative (de-obligations), so a year with ≤ 0 is never used as a base.
 * Pure, so it is unit-tested and renders identically for Google and visitors.
 */
import { formatMoneyCompact as fmtMoney } from '@/lib/format-money';

export interface SummaryInput {
  name: string;
  city?: string | null;
  state?: string | null;
  totalObligated: number | null;
  awardCount: number | null;
  agencyCount: number | null;
  yearly: ReadonlyArray<{ fiscal_year: number; total_obligated: number }>;
  topAgencies: ReadonlyArray<{ awarding_agency: string; total_amount: number; pct_of_total: number }>;
  topNaics: ReadonlyArray<{ naics_code: string; naics_description: string | null; total_amount: number; award_count: number }>;
  /** null = the read failed (omit); [] = none found (also omitted — absence in one table is not a claim). */
  expiring: ReadonlyArray<{ end: string | null; agency: string | null }> | null;
  /** The read's limit: a full list means "at least N", never exactly N. */
  expiringLimit?: number;
  now?: Date;
}

const SMALL = new Set(['of', 'and', 'the', 'for', 'on', 'in', 'to', 'at', 'by']);
/** "DEPARTMENT OF THE NAVY" → "Department of the Navy"; leaves mixed-case input alone. */
export function tidyAgency(s: string): string {
  if (s !== s.toUpperCase()) return s.trim();
  return s
    .toLowerCase()
    .split(/\s+/)
    .map((w, i) => (i > 0 && SMALL.has(w) ? w : w.charAt(0).toUpperCase() + w.slice(1)))
    .join(' ')
    .trim();
}

/** Federal fiscal year containing `d` (FY starts 1 October). */
export function federalFiscalYear(d: Date): number {
  return d.getUTCMonth() >= 9 ? d.getUTCFullYear() + 1 : d.getUTCFullYear();
}

const pct = (x: number) => `${Math.round(x * 100)}%`;
const positive = (n: number | null | undefined): n is number => typeof n === 'number' && Number.isFinite(n) && n > 0;

function fmtDate(iso: string): string | null {
  const d = new Date(`${iso.slice(0, 10)}T00:00:00Z`);
  if (Number.isNaN(d.getTime())) return null;
  return d.toLocaleDateString('en-US', { month: 'long', year: 'numeric', timeZone: 'UTC' });
}

export function buildContractorSummary(input: SummaryInput): string[] {
  const out: string[] = [];
  const { name } = input;

  // 1. Who and how much.
  if (positive(input.totalObligated) && positive(input.awardCount)) {
    const where = input.city && input.state ? `, based in ${tidyAgency(input.city)}, ${input.state},` : '';
    const agencies = positive(input.agencyCount)
      ? ` from ${input.agencyCount} ${input.agencyCount === 1 ? 'agency' : 'agencies'}`
      : '';
    out.push(
      `${name}${where} has received ${fmtMoney(input.totalObligated)} in federal contract obligations across ${input.awardCount.toLocaleString('en-US')} awards${agencies}.`,
    );
  }

  // 2. Who buys from them.
  const agencies = input.topAgencies.filter((a) => a.awarding_agency && positive(a.total_amount) && positive(a.pct_of_total));
  if (agencies.length > 0) {
    const [first, ...rest] = agencies;
    if (first.pct_of_total >= 0.995) {
      out.push(`All of its federal obligations come from the ${tidyAgency(first.awarding_agency)}.`);
    } else {
      const next = rest.slice(0, 2).map((a) => `${tidyAgency(a.awarding_agency)} (${pct(a.pct_of_total)})`);
      out.push(
        `Its largest customer is the ${tidyAgency(first.awarding_agency)}, at ${pct(first.pct_of_total)} of obligations` +
          (next.length ? `, followed by ${next.join(' and ')}.` : '.'),
      );
    }
  }

  // 3. What they do.
  const naics = input.topNaics.find((n) => n.naics_code && positive(n.total_amount) && positive(n.award_count));
  if (naics) {
    const desc = naics.naics_description ? ` (${naics.naics_description.trim().toLowerCase()})` : '';
    out.push(
      `Its largest line of work is NAICS ${naics.naics_code}${desc}: ${fmtMoney(naics.total_amount)} across ${naics.award_count.toLocaleString('en-US')} ${naics.award_count === 1 ? 'award' : 'awards'}.`,
    );
  }

  // 4. Direction, from the two most recent complete fiscal years.
  const currentFy = federalFiscalYear(input.now ?? new Date());
  const complete = input.yearly
    .filter((y) => y.fiscal_year < currentFy)
    .sort((a, b) => a.fiscal_year - b.fiscal_year);
  const last = complete[complete.length - 1];
  const prev = complete[complete.length - 2];
  if (last && prev && last.fiscal_year === prev.fiscal_year + 1 && positive(prev.total_obligated) && positive(last.total_obligated)) {
    const change = (last.total_obligated - prev.total_obligated) / prev.total_obligated;
    const dir = Math.abs(change) < 0.005 ? 'about level with' : change > 0 ? `up ${pct(change)} from` : `down ${pct(-change)} from`;
    out.push(`In FY${last.fiscal_year} it received ${fmtMoney(last.total_obligated)}, ${dir} FY${prev.fiscal_year}.`);
  }

  // 5. What is coming up for recompete.
  const ends = (input.expiring ?? []).filter((e) => e.end && fmtDate(e.end));
  if (ends.length > 0) {
    const first = ends[0];
    const firstDate = fmtDate(first.end as string);
    const at = first.agency ? ` with the ${tidyAgency(first.agency)}` : '';
    out.push(
      ends.length === 1
        ? `One of its contracts${at} is scheduled to end in ${firstDate}, which can open it to recompetition.`
        : `${ends.length >= (input.expiringLimit ?? Infinity) ? `At least ${ends.length}` : ends.length} of its contracts are scheduled to end soon; the next${at} ends in ${firstDate}.`,
    );
  }

  return out;
}
